import shutil
import subprocess
from pathlib import Path
from agents import function_tool

UPLOADS_ROOT = Path("/srv/chat/uploads")
QUARANTINE_ROOT = Path("/srv/chat/quarantine")


def _parse_clamscan_output(output: str) -> list[tuple[str, str]]:
    hits = []
    for line in output.splitlines():
        if not line.endswith(" FOUND"):
            continue
        path_part, _, rest = line.rpartition(": ")
        signature = rest[: -len(" FOUND")].strip()
        if path_part:
            hits.append((path_part, signature))
    return hits


@function_tool
def quarantine_infected_attachments(channel_id: str) -> dict:
    channel_dir = UPLOADS_ROOT / channel_id
    if not channel_dir.is_dir():
        return {"channel_id": channel_id, "error": "No uploads folder for this channel."}

    proc = subprocess.run(
        ["clamscan", "-r", "--infected", "--no-summary", str(channel_dir)],
        capture_output=True,
        text=True,
        timeout=900,
    )
    if proc.returncode not in (0, 1):
        return {"channel_id": channel_id, "error": proc.stderr.strip() or "Scanner failed."}

    hits = _parse_clamscan_output(proc.stdout)
    target_dir = QUARANTINE_ROOT / channel_id
    if hits:
        target_dir.mkdir(parents=True, exist_ok=True)

    quarantined = []
    for file_path, signature in hits:
        src = Path(file_path)
        if not src.exists():
            continue
        dest = target_dir / src.name
        counter = 1
        while dest.exists():
            dest = target_dir / f"{src.stem}_{counter}{src.suffix}"
            counter += 1
        shutil.move(str(src), str(dest))
        quarantined.append({"original": str(src), "quarantined_to": str(dest), "signature": signature})

    return {
        "channel_id": channel_id,
        "scanned_dir": str(channel_dir),
        "infected_count": len(quarantined),
        "quarantined": quarantined,
    }
